import { readDeliveryLocation } from './delivery-context.js';
import { currentBuyer, registerBuyer, loginBuyer, logoutBuyer, updateBuyer, saveBuyerAddress, removeBuyerAddress } from './buyer-account.js';
const buyerEscape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const buyerInput=(label,name,value='',type='text',extra='')=>`<label class="field-label">${label}<input class="panel-input" name="${name}" type="${type}" value="${buyerEscape(value)}" ${extra}></label>`;
export function createBuyerAccountUI({modal,onOrders,onLogout}){
 function auth(mode='login',done=()=>account()){
  const register=mode==='register',location=readDeliveryLocation();modal(register?'Crie sua conta':'Entre na sua conta',`<div class="buyer-account"><p class="order-notice">Demonstração local. Use dados e senha fictícios. O cadastro fica neste navegador; você inicia deslogado a cada abertura ou recarga.</p><div class="account-tabs"><button class="btn ${register?'secondary':''}" data-auth-mode="login">Entrar</button><button class="btn ${register?'':'secondary'}" data-auth-mode="register">Criar conta</button></div><form id="buyer-auth">${register?buyerInput('Nome completo','name','','text','required maxlength="100" autocomplete="name"'):''}${buyerInput('E-mail','email','','email','required autocomplete="email"')}${register?buyerInput('Telefone com DDD','phone','','tel','required maxlength="20" autocomplete="tel"'):''}${buyerInput('Senha demonstrativa','password','','password','required minlength="8" maxlength="128" autocomplete="'+(register?'new-password':'current-password')+'"')}${register?buyerInput('Confirme a senha','confirmPassword','','password','required minlength="8" maxlength="128" autocomplete="new-password"'):''}${register?`<h3>Confirme seu endereço</h3><p>Seu CEP foi preenchido a partir da localização escolhida. Complete os dados abaixo.</p><div class="form-two">${buyerInput('CEP da rua','cep',location?.cep||'','text','required maxlength="9" autocomplete="postal-code"')}${buyerInput('Cidade','city',location?.city||'','text','required')}${buyerInput('Rua / avenida','street','','text','required maxlength="150" autocomplete="address-line1"')}${buyerInput('Número','number','','text','required maxlength="20"')}${buyerInput('Bairro','neighborhood','','text','required maxlength="100"')}${buyerInput('UF','state','PR','text','required maxlength="2"')}${buyerInput('Complemento','complement','','text','maxlength="100"')}</div>`:''}<button class="btn" type="submit">${register?'Cadastrar e entrar':'Entrar'}</button><p class="account-feedback" role="alert"></p></form></div>`);
  const f=document.querySelector('#buyer-auth');document.querySelectorAll('[data-auth-mode]').forEach(b=>b.onclick=()=>auth(b.dataset.authMode,done));f.onsubmit=async e=>{e.preventDefault();const button=f.querySelector('[type=submit]');button.disabled=true;try{const data=Object.fromEntries(new FormData(f));if(register)await registerBuyer(data);else await loginBuyer(data.email,data.password);done();}catch(err){f.querySelector('.account-feedback').textContent=err.message;}finally{button.disabled=false;}};
 }
 function account(page='overview'){
  const user=currentBuyer();if(!user){auth();return}
  modal('Minha conta',`<div class="buyer-account"><div class="account-heading"><div><span class="eyebrow">SEU ESPAÇO NO TEM LOGO ALI</span><h3>Bem-vindo, ${buyerEscape(user.name)}!</h3></div><button class="text-link" data-account="logout">Sair</button></div><nav class="account-tabs" aria-label="Minha conta"><button data-account="overview">Resumo</button><button data-account="profile">Meu cadastro</button><button data-account="addresses">Meus endereços</button><button data-account="orders">Meus pedidos</button></nav><div id="account-content"></div><p id="account-feedback" role="status"></p></div>`);
  document.querySelectorAll('[data-account]').forEach(b=>b.onclick=()=>{if(b.dataset.account==='logout'){logoutBuyer();onLogout();modal('Você saiu da conta','<p>Até logo! Entre novamente quando quiser continuar suas compras.</p>');return}if(b.dataset.account==='orders'){onOrders();return}account(b.dataset.account)});
  const host=document.querySelector('#account-content');
  if(page==='overview'){host.innerHTML=`<div class="account-grid"><button class="account-tile" id="account-profile"><b>Meu cadastro</b><span>${buyerEscape(user.email)}</span></button><button class="account-tile" id="account-addresses"><b>Endereços de entrega e cobrança</b><span>${user.addresses.length} endereço(s) salvo(s)</span></button><button class="account-tile" id="account-orders"><b>Pedidos e downloads</b><span>Acompanhe, converse com a loja ou compre novamente.</span></button></div>`;host.querySelector('#account-profile').onclick=()=>account('profile');host.querySelector('#account-addresses').onclick=()=>account('addresses');host.querySelector('#account-orders').onclick=onOrders;}
  if(page==='profile'){host.innerHTML=`<form id="buyer-profile"><div class="form-two">${buyerInput('Nome completo','name',user.name,'text','required maxlength="100"')}${buyerInput('E-mail','email',user.email,'email','required')}${buyerInput('Telefone com DDD','phone',user.phone,'tel','required maxlength="20"')}${buyerInput('CPF demonstrativo (opcional)','cpf',user.cpf,'text','maxlength="14"')}${buyerInput('Data de nascimento (opcional)','birthday',user.birthday,'date')}</div><h3>Segurança da conta demonstrativa</h3><p>Para alterar e-mail ou senha, confirme a senha atual. Deixe a nova senha vazia para mantê-la.</p>${buyerInput('Senha atual','currentPassword','','password','autocomplete="current-password"')}${buyerInput('Nova senha','password','','password','minlength="8" maxlength="128" autocomplete="new-password"')}${buyerInput('Confirmar nova senha','confirmPassword','','password','autocomplete="new-password"')}<button class="btn">Salvar cadastro</button><p class="account-feedback" role="alert"></p></form>`;host.querySelector('form').onsubmit=async e=>{e.preventDefault();const f=e.target,b=f.querySelector('button');b.disabled=true;try{await updateBuyer(Object.fromEntries(new FormData(f)));account('profile');document.querySelector('#account-feedback').textContent='Cadastro atualizado.'}catch(err){f.querySelector('.account-feedback').textContent=err.message}finally{b.disabled=false}};}
  if(page==='addresses'){host.innerHTML=`<h3>Endereços de entrega e cobrança</h3><p>Você pode usar endereços diferentes para receber e para cobrança.</p><div class="address-list">${user.addresses.map(a=>`<article class="address-card"><b>${buyerEscape(a.label)}</b><p>${buyerEscape(a.name)}<br>${buyerEscape(a.street)}, ${buyerEscape(a.number)} · ${buyerEscape(a.neighborhood)}<br>${buyerEscape(a.city)} / ${buyerEscape(a.state)} · ${buyerEscape(a.cep)}<br>${buyerEscape(a.complement)}</p><small>${user.defaultDelivery===a.id?'Padrão de entrega ':''}${user.defaultBilling===a.id?' · Padrão de cobrança':''}</small><div><button class="text-link" data-edit-address="${a.id}">Editar</button><button class="text-link" data-remove-address="${a.id}">Excluir</button></div></article>`).join('')||'<p>Você ainda não cadastrou um endereço.</p>'}</div><button class="btn" id="new-buyer-address">Adicionar endereço</button><div id="address-editor"></div>`;host.querySelector('#new-buyer-address').onclick=()=>addressForm();host.querySelectorAll('[data-edit-address]').forEach(b=>b.onclick=()=>addressForm(user.addresses.find(a=>a.id===b.dataset.editAddress)));host.querySelectorAll('[data-remove-address]').forEach(b=>b.onclick=()=>{try{removeBuyerAddress(b.dataset.removeAddress);account('addresses')}catch(err){document.querySelector('#account-feedback').textContent=err.message}});}
 }
 function addressForm(a={}){const user=currentBuyer(),host=document.querySelector('#address-editor');host.innerHTML=`<form id="buyer-address"><h3>${a.id?'Editar':'Adicionar'} endereço</h3><input type="hidden" name="id" value="${a.id||''}"><div class="form-two">${buyerInput('Identificação (ex.: Casa)','label',a.label,'text','required maxlength="50"')}${buyerInput('Destinatário','name',a.name||user.name,'text','required maxlength="100"')}${buyerInput('CEP','cep',a.cep||readDeliveryLocation()?.cep,'text','required maxlength="9"')}${buyerInput('Rua / avenida','street',a.street,'text','required maxlength="150"')}${buyerInput('Número','number',a.number,'text','required maxlength="20"')}${buyerInput('Bairro','neighborhood',a.neighborhood,'text','required maxlength="100"')}${buyerInput('Cidade','city',a.city||readDeliveryLocation()?.city,'text','required maxlength="100"')}${buyerInput('UF','state',a.state||'PR','text','required maxlength="2"')}${buyerInput('Complemento','complement',a.complement,'text','maxlength="100"')}</div><label><input type="checkbox" name="delivery" ${!user.defaultDelivery||user.defaultDelivery===a.id?'checked':''}> Usar como padrão de entrega</label><label><input type="checkbox" name="billing" ${!user.defaultBilling||user.defaultBilling===a.id?'checked':''}> Usar como padrão de cobrança</label><button class="btn">Salvar endereço</button><p class="account-feedback" role="alert"></p></form>`;host.querySelector('form').onsubmit=e=>{e.preventDefault();try{saveBuyerAddress(Object.fromEntries(new FormData(e.target)));account('addresses');document.querySelector('#account-feedback').textContent='Endereço salvo.'}catch(err){e.target.querySelector('.account-feedback').textContent=err.message}};host.scrollIntoView({block:'nearest'});}
 return {account,auth,requireLogin:done=>currentBuyer()?done():auth('login',done)};
}
